    // frame the real bounds of the creature (+ fox) inside the clear band below the notes card and above the controls
    const Hh = H(), Ww = W(), ins = getInsets(), top = Math.min(ins.top, Hh * 0.4), bot = Math.min(ins.bottom, Hh * 0.6), band = Math.max(120, Hh - top - bot - 16);
    box.makeEmpty(); if (cur && cur.userData.frame) { const f = cur.userData.frame; box.expandByPoint(v1.set(-1.7, 0, -1.2)); box.expandByPoint(v1.set(1.7, 2.6, 2.6)); } else if (cur) visBox(cur); if (showFox) visBox(fox); if (box.isEmpty()) box.set(new THREE.Vector3(-1, 0, -1), new THREE.Vector3(1, 1.5, 1));
    const c = box.getCenter(v1.clone()), sz = box.getSize(new THREE.Vector3()), tv = Math.tan(camera.fov * Math.PI / 360), tvb = tv * band / Hh, th = tv * camera.aspect;
    const D = Math.min(24, (Math.max(sz.y / 2 / tvb, Math.max(sz.x, sz.z) / 2 / th) + Math.max(sz.x, sz.z) / 2) * 1.05 * (dist / 7.2));
    camera.position.set(c.x + Math.sin(yaw) * D * Math.cos(pitch), c.y + Math.sin(pitch) * D, c.z + Math.cos(yaw) * D * Math.cos(pitch)); camera.lookAt(c);
