    setBake(v) { bake = v; if (cur) setCreature(cur.userData.variant); },
    setTurntable(v) { turn = v; if (!v) table.rotation.y = 0; push(); }, setTells(v) { tells = v; push(); }, setFox(v) { showFox = v; push(); },
    setLoop(v) { loop = v; loopI = 0; play(v ? 'move' : 'idle'); },
    setAI(v) { if (v && cur) { loop = false; turn = false; table.rotation.y = 0; setCreature(cur.userData.variant); ai = createBrain(cur, ck); foxHp = 100; } else { ai = null; fox.position.set(-2.9, 0, 0.4); fox.rotation.y = 0.5; if (cur) setCreature(cur.userData.variant); } push(); },
